#define I2C_COMMAND15_ACK_VAL_V  0x1

#define I2C_COMMAND15_ACK_EXP_S  9
#define I2C_COMMAND15_ACK_EXP_M  0x00000200
#define I2C_COMMAND15_ACK_EXP_V  0x1

#define I2C_COMMAND15_ACK_EN_S  8
#define I2C_COMMAND15_ACK_EN_M  0x00000100
#define I2C_COMMAND15_ACK_EN_V  0x1

#define I2C_COMMAND15_BYTE_NUM_S  0
#define I2C_COMMAND15_BYTE_NUM_M  0x000000FF
#define I2C_COMMAND15_BYTE_NUM_V  0xFF

/* Accessor macros */
#define REG_READ(addr)        (*(volatile uint32_t *)(addr))
#define REG_WRITE(addr, val)  (*(volatile uint32_t *)(addr) = (val))
#define REG_SET_BITS(addr, mask)    REG_WRITE((addr), REG_READ(addr) | (mask))
#define REG_CLR_BITS(addr, mask)    REG_WRITE((addr), REG_READ(addr) & ~(mask))
#define REG_SET_FIELD(addr, field, val)  \
    REG_WRITE((addr), (REG_READ(addr) & ~field##_M) | (((val) & field##_V) << field##_S))
#define REG_GET_FIELD(addr, field)  \
    ((REG_READ(addr) & field##_M) >> field##_S)

#endif /* I2C0_REGS_H */
